def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    pairs = [(edge.get('i', -1), edge.get('j', -1), edge.get('distance_A')) for edge in s.get('neighbors') or [] if 0 <= edge.get('i', -1) < n and 0 <= edge.get('j', -1) < n and edge.get('distance_A') is not None and edge.get('distance_A') > 0]
    result = 0.0
    total = 0.0
    for i in range(n):
        if occ[i] > 0:
            distances = [d for center, j, d in pairs if center == i and occ[j] > 0]
            if distances:
                cutoff = 1.25 * min(distances)
                outer = [d for d in distances if d > cutoff]
                if outer:
                    shell_end = max(d for d in distances if d <= cutoff)
                    gap = float(np.log(min(outer) / max(shell_end, 1e-12)))
                    result += occ[i] * max(0.0, gap)
                    total += occ[i]
    if total <= 0:
        return 0.0
    return result / total

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    pairs = [(edge.get('i', -1), edge.get('j', -1), edge.get('distance_A')) for edge in s.get('neighbors') or [] if 0 <= edge.get('i', -1) < n and 0 <= edge.get('j', -1) < n and edge.get('distance_A') is not None and edge.get('distance_A') > 0]
    result = 0.0
    total = 0.0
    for i in range(n):
        if occ[i] > 0:
            nearby = [(d, occ[j]) for center, j, d in pairs if center == i and occ[j] > 0]
            if nearby:
                cutoff = 1.25 * min(d for d, o in nearby)
                shell = [(d, o) for d, o in nearby if d <= cutoff]
                weight = sum(o for d, o in shell)
                if weight > 0:
                    mean = sum(o * d for d, o in shell) / weight
                    variance = sum(o * (d - mean) ** 2 for d, o in shell) / weight
                    result += occ[i] * variance / max(mean * mean, 1e-24)
                    total += occ[i]
    if total <= 0:
        return 0.0
    return max(0.0, result / total)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    atoms = 0.0
    known = 0.0
    electrons = 0.0
    for t in sites:
        o = max(0.0, t.get('occupancy', 1.0) or 0.0)
        atoms += o
        v = (props.get(t.get('element')) or {}).get('valence_electrons')
        if v is not None and v >= 0:
            known += o
            electrons += o * v
    if atoms <= 0 or known <= 0:
        return 0.0
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is not None and volume > 0:
        return electrons * atoms / (known * volume)
    volume_per_atom = s.get('volume_per_atom_A3')
    if volume_per_atom is None or volume_per_atom <= 0:
        volume_per_atom = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if volume_per_atom is None or volume_per_atom <= 0:
        return 0.0
    return electrons / (known * volume_per_atom)
